// Common landing point for both entry paths (the real "When Executed by
// Parent" caller, and "Test manually" for standalone testing), so the
// normalizer downstream can reliably reference ONE upstream node by name
// for account_id/channel, regardless of which trigger actually ran.
return $input.all();

// Maps kaitoeasyapi/twitter-x-data-tweet-scraper output (one item per tweet) into the
// standard row schema the main report expects.
//
// The actor returns a flat list of tweets for ALL accounts in the run, so
// each tweet is matched back to its account by author.userName against the
// items that came out of 'Prepare request' (not by item index).
// Retweets, replies and quotes are dropped: only the account's own original posts count.
// Accounts with no tweets get a skipped row (ignored by Build report).
// viewCount is mapped if the actor returns it, otherwise stays null (N/A).

const norm = s => String(s || '').replace(/^@/, '').toLowerCase();

const accounts = $('Prepare request').all().map(i => i.json);
const byHandle = {};
accounts.forEach(a => { byHandle[norm(a.account_id)] = a; });

const MAX_PER_ACCOUNT = 10; // newest N tweets kept per account
const seen = new Set();
const found = new Set();
const results = [];

const tweets = $input.all()
  .map(i => i.json || {})
  .sort((a, b) => new Date(b.createdAt || 0) - new Date(a.createdAt || 0));
const perAccount = {};

tweets.forEach(t => {
  if (!t.id || t.type === 'mock_tweet') return;
  if (t.isRetweet || t.isReply || t.isQuote) return; // original posts only
  const handle = norm(t.author && t.author.userName);
  const acc = byHandle[handle];
  if (!acc || seen.has(String(t.id))) return;
  perAccount[handle] = (perAccount[handle] || 0) + 1;
  if (perAccount[handle] > MAX_PER_ACCOUNT) return;
  seen.add(String(t.id));
  found.add(handle);

  const typeLabel = 'Post';
  const d = t.createdAt ? new Date(t.createdAt) : null;

  results.push({
    json: {
      platform: 'X',
      channel: acc.channel,
      account_id: acc.account_id,
      likes_label: 'Likes',
      id: String(t.id),
      title: String(t.text || '').slice(0, 100),
      type: typeLabel,
      views: t.viewCount ?? null,
      likes: t.likeCount ?? null,
      comments: t.replyCount ?? null,
      shares: (t.retweetCount ?? 0) + (t.quoteCount ?? 0),
      permalink: t.url || t.twitterUrl || `https://x.com/${acc.account_id}/status/${t.id}`,
      created_at: d && !isNaN(d) ? d.toISOString() : null,
      insights_ok: true,
    },
  });
});

accounts.forEach(a => {
  if (!found.has(norm(a.account_id))) {
    results.push({
      json: {
        platform: 'X',
        channel: a.channel,
        skipped: true,
        reason: 'No tweets returned by Apify (account empty, actor failed, or credential/plan problem).',
      },
    });
  }
});

return results;

// Test data for standalone runs -- the real caller is the main workflow's
// Accounts config, which passes one item like this per enabled X account.
// account_id must be the bare handle (x.com/<handle>), no @.
return [
  { json: { platform: 'X', channel: 'Brand B', account_id: 'brand_b' } },
  { json: { platform: 'X', channel: 'Brand A', account_id: 'brandA' } },
];
